import os
import requests

def normalize_expense(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["MINDEE_API_KEY"]
    endpoint = "https://api.mindee.net/v1/products/mindee/expense_receipts/v5/predict"
    headers = {"Authorization": f"Token {api_key}"}
    files = {}
    data = {}

    if isinstance(payload, dict):
        file_obj = payload.get("file")
        if file_obj is not None:
            if hasattr(file_obj, "read"):
                files["document"] = (
                    getattr(file_obj, "name", "document"),
                    file_obj,
                    payload.get("content_type", "application/octet-stream"),
                )
            elif isinstance(file_obj, (bytes, bytearray)):
                files["document"] = (
                    payload.get("filename", "document"),
                    file_obj,
                    payload.get("content_type", "application/octet-stream"),
                )
        elif payload.get("file_bytes") is not None:
            files["document"] = (
                payload.get("filename", "document"),
                payload["file_bytes"],
                payload.get("content_type", "application/octet-stream"),
            )
        elif payload.get("document_url"):
            data["document_url"] = payload["document_url"]
        else:
            raise ValueError("payload must include 'file', 'file_bytes', or 'document_url'")
    elif isinstance(payload, str):
        data["document_url"] = payload
    elif isinstance(payload, (bytes, bytearray)):
        files["document"] = ("document", payload, "application/octet-stream")
    elif hasattr(payload, "read"):
        files["document"] = (
            getattr(payload, "name", "document"),
            payload,
            "application/octet-stream",
        )
    else:
        raise TypeError("Unsupported payload type")

    response = requests.post(endpoint, headers=headers, files=files or None, data=data or None, timeout=config.get("timeout", 60))
    response.raise_for_status()
    body = response.json()
    prediction = body.get("document", {}).get("inference", {}).get("prediction", {})

    result = {
        "vendor_name": (prediction.get("supplier_name") or {}).get("value"),
        "vendor_address": (prediction.get("supplier_address") or {}).get("value"),
        "vendor_phone": (prediction.get("supplier_phone_number") or {}).get("value"),
        "invoice_number": (prediction.get("receipt_number") or {}).get("value"),
        "date": (prediction.get("date") or {}).get("value"),
        "time": (prediction.get("time") or {}).get("value"),
        "currency": (prediction.get("locale") or {}).get("currency"),
        "locale": {
            "language": (prediction.get("locale") or {}).get("language"),
            "country": (prediction.get("locale") or {}).get("country"),
        },
        "amounts": {
            "subtotal": (prediction.get("total_net") or {}).get("value"),
            "tax": (prediction.get("total_tax") or {}).get("value"),
            "tip": (prediction.get("tip") or {}).get("value"),
            "total": (prediction.get("total_amount") or {}).get("value"),
        },
        "payment": {
            "method": (prediction.get("payment_method") or {}).get("value"),
            "card_number": (prediction.get("card_number") or {}).get("value"),
        },
        "category": (prediction.get("category") or {}).get("value"),
        "subcategories": [
            item.get("value") if isinstance(item, dict) else item
            for item in (prediction.get("subcategories") or [])
        ],
        "taxes": [
            {
                "rate": tax_line.get("tax_rate"),
                "base": tax_line.get("base"),
                "value": tax_line.get("value"),
                "code": tax_line.get("code"),
            }
            for tax_line in (prediction.get("taxes") or [])
        ],
        "line_items": [
            {
                "description": line.get("description"),
                "quantity": line.get("quantity"),
                "unit_price": line.get("unit_price"),
                "total_amount": line.get("total_amount"),
                "product_code": line.get("product_code"),
            }
            for line in (prediction.get("line_items") or [])
        ],
        "raw": body,
        "provider": "mindee",
        "model": "mindee/expense_receipts/v5",
    }
    return result
